<script setup lang="ts">
import { computed, ref } from "vue";
import { downloadBulkResourceErrorReport, downloadBulkResourceTemplate, importBulkResources, validateBulkResources } from "../api";
import type { BulkResourceValidation } from "../api/contracts";
import { useCatalogsStore } from "../stores/catalogs";
import Modal from "./Modal.vue";

const emit = defineEmits<{ close: [] }>();
const catalogs = useCatalogsStore();
const file = ref<File | null>(null), format = ref<"xlsx" | "xls">("xlsx"), result = ref<BulkResourceValidation | null>(null), error = ref(""), busy = ref(false);
const fileError = computed(() => file.value && (!/\.xlsx?$/i.test(file.value.name) || file.value.size > 5 * 1024 * 1024) ? "Selecciona un archivo .xlsx o .xls de máximo 5 MB." : "");
function save(blob: Blob, name: string) { const url = URL.createObjectURL(blob), link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
async function template() { busy.value = true; error.value = ""; try { save(await downloadBulkResourceTemplate(format.value), `plantilla-recursos.${format.value}`); } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible descargar la plantilla."; } finally { busy.value = false; } }
function choose(event: Event) { const selected = (event.target as HTMLInputElement).files?.[0] ?? null; file.value = selected; result.value = null; error.value = ""; }
async function validate() { if (!file.value || fileError.value) return; busy.value = true; error.value = ""; try { result.value = (await validateBulkResources(file.value)).data; } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible validar el archivo."; } finally { busy.value = false; } }
async function report() { if (!file.value) return; busy.value = true; try { save(await downloadBulkResourceErrorReport(file.value), `reporte-errores.${file.value.name.split(".").pop()}`); } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible descargar el reporte."; } finally { busy.value = false; } }
async function submit() { if (!file.value || !result.value?.ready) return; busy.value = true; error.value = ""; try { const response = (await importBulkResources(file.value)).data; if (!response.ready) { result.value = response; return; } catalogs.notice = `Se registraron ${response.validRows} recursos.`; await catalogs.refresh(); emit("close"); } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible confirmar la carga."; } finally { busy.value = false; } }
</script>
<template>
  <Modal wide title="Carga masiva de recursos" description="Registra múltiples endpoints de forma segura, con validación previa para cada aplicación." submit-label="Confirmar carga" :submit-disabled="!result?.ready" :busy="busy" :error="error || fileError" eyebrow="IMPORTAR EXCEL" @close="emit('close')" @submit="submit">
    <div class="bulk-form">
      <ol class="progress" aria-label="Progreso de la carga">
        <li class="active"><b>01</b><span>Plantilla</span></li><li :class="{ active: file }"><b>02</b><span>Archivo</span></li><li :class="{ active: result }"><b>03</b><span>Validación</span></li>
      </ol>
      <section class="bulk-step">
        <div class="step-heading"><span class="step-number">01</span><div><strong>Descarga una plantilla</strong><p>Elige el formato compatible con tu herramienta y conserva los encabezados.</p></div></div>
        <div class="format-picker" role="group" aria-label="Formato de plantilla"><button type="button" :class="{ selected: format === 'xlsx' }" @click="format = 'xlsx'"><b>.XLSX</b><span>Excel actual</span></button><button type="button" :class="{ selected: format === 'xls' }" @click="format = 'xls'"><b>.XLS</b><span>Excel 97–2003</span></button><button type="button" class="download" :disabled="busy" @click="template">Descargar plantilla <span>↓</span></button></div>
      </section>
      <section class="bulk-step">
        <div class="step-heading"><span class="step-number">02</span><div><strong>Sube el archivo completado</strong><p>Una fila equivale a un recurso. Puedes incluir aplicaciones distintas autorizadas.</p></div></div>
        <label class="dropzone" :class="{ uploaded: file, invalid: fileError }"><input type="file" accept=".xlsx,.xls,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" :disabled="busy" @change="choose" /><span class="file-mark">{{ file ? '✓' : '↑' }}</span><span><b>{{ file ? file.name : 'Selecciona tu archivo Excel' }}</b><small>{{ file ? `${Math.ceil(file.size / 1024)} KB · listo para validar` : 'Formatos .xlsx y .xls · tamaño máximo de 5 MB' }}</small></span><span class="browse">{{ file ? 'Cambiar' : 'Examinar' }}</span></label>
        <div class="step-actions"><span>Validamos estructura, tenant, permisos y duplicados antes de crear recursos.</span><button type="button" class="validate" :disabled="busy || !file || !!fileError" @click="validate">Validar archivo <span>→</span></button></div>
      </section>
      <section v-if="result" class="bulk-step result" :class="{ valid: result.ready }">
        <div class="step-heading"><span class="step-number">03</span><div><strong>{{ result.ready ? 'Archivo preparado para importar' : 'Se requieren correcciones' }}</strong><p>{{ result.ready ? 'Todo está validado. Puedes confirmar la creación del lote.' : 'Descarga el reporte, corrige el archivo y vuelve a validarlo.' }}</p></div><span class="status-pill" :class="result.ready ? 'ok' : 'warning'">{{ result.ready ? 'LISTO' : 'REVISAR' }}</span></div>
        <div class="summary"><div><b>{{ result.totalRows }}</b><span>Filas leídas</span></div><div class="good"><b>{{ result.validRows }}</b><span>Válidas</span></div><div :class="{ bad: result.invalidRows }"><b>{{ result.invalidRows }}</b><span>Con errores</span></div></div>
        <div v-if="result.errors.length" class="error-block"><div class="error-toolbar"><strong>Errores detectados</strong><button type="button" class="report" :disabled="busy" @click="report">Descargar Excel anotado <span>↓</span></button></div><div class="errors" role="alert"><table><thead><tr><th>Fila</th><th>Campo</th><th>Código</th><th>Descripción</th></tr></thead><tbody><tr v-for="issue in result.errors" :key="`${issue.row}-${issue.field}-${issue.code}`"><td>{{ issue.row || '—' }}</td><td>{{ issue.field }}</td><td><code>{{ issue.code }}</code></td><td>{{ issue.description }}</td></tr></tbody></table></div></div>
      </section>
    </div>
  </Modal>
</template>
<style scoped>
.bulk-form { display:grid; gap:14px; padding-bottom:4px; }.progress { display:flex; gap:0; list-style:none; padding:0; margin:0 0 3px; }.progress li { flex:1; display:flex; align-items:center; gap:8px; color:var(--faint); font:500 10px 'IBM Plex Mono', monospace; letter-spacing:.05em; }.progress li:not(:last-child)::after { content:""; height:1px; background:var(--line); flex:1; margin-left:5px; }.progress b { color:var(--faint); }.progress .active { color:var(--green-ink); }.progress .active b { color:var(--green); }.bulk-step { display:grid; gap:14px; border:1px solid var(--soft-line); border-radius:10px; padding:17px; background:linear-gradient(135deg, #fff, #fcfdfc); }.step-heading { display:flex; align-items:flex-start; gap:10px; }.step-heading>div { flex:1; }.step-heading strong { font-size:13px; color:var(--ink); }.step-heading p { margin:4px 0 0; color:var(--text); font-size:11px; line-height:1.45; }.step-number { flex:none; width:25px; height:25px; border-radius:7px; display:grid; place-items:center; background:var(--green-wash); color:var(--green); font:500 10px 'IBM Plex Mono',monospace; }.format-picker { display:grid; grid-template-columns:1fr 1fr auto; gap:8px; }.format-picker button { min-height:48px; text-align:left; border:1px solid var(--line); border-radius:7px; background:var(--paper); color:var(--text); padding:8px 10px; transition:.16s ease; }.format-picker button:not(.download):hover { border-color:rgba(1,139,81,.4); }.format-picker button.selected { border-color:var(--green); background:var(--green-tint); box-shadow:inset 0 0 0 1px var(--green); }.format-picker b,.format-picker span { display:block; }.format-picker b { color:var(--ink); font:500 10px 'IBM Plex Mono',monospace; }.format-picker span { margin-top:3px; font-size:10px; }.format-picker .download,.validate { border:0; background:var(--ink); color:#fff; font-weight:600; font-size:11px; padding:0 13px; }.download span,.validate span,.report span { margin-left:5px; color:var(--green); font-size:15px; }.dropzone { min-height:82px; display:flex; align-items:center; gap:12px; border:1px dashed rgba(17,19,18,.25); border-radius:8px; padding:13px; background:var(--field); transition:.16s ease; cursor:pointer; }.dropzone:hover { border-color:var(--green); background:var(--green-tint); }.dropzone.uploaded { border-style:solid; border-color:rgba(1,139,81,.3); background:var(--green-tint); }.dropzone.invalid { border-color:var(--red); }.dropzone input { position:absolute; width:1px; height:1px; opacity:0; pointer-events:none; }.file-mark { flex:none; width:34px; height:34px; border-radius:50%; display:grid; place-items:center; background:var(--paper); color:var(--green); font:600 16px 'IBM Plex Mono',monospace; box-shadow:0 1px 3px rgba(17,19,18,.08); }.dropzone>span:nth-child(2) { min-width:0; flex:1; display:grid; gap:3px; }.dropzone b { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--ink); font-size:12px; }.dropzone small { color:var(--text); font-size:10px; }.browse { color:var(--green-ink); font-size:11px; font-weight:600; }.step-actions { display:flex; justify-content:space-between; align-items:center; gap:12px; color:var(--faint); font-size:10px; line-height:1.4; }.validate { height:34px; flex:none; border-radius:6px; }.result { background:linear-gradient(135deg,rgba(1,139,81,.045),#fff); }.result:not(.valid) { background:linear-gradient(135deg,rgba(185,61,60,.045),#fff); }.status-pill { align-self:center; border-radius:20px; padding:5px 8px; font:500 9px 'IBM Plex Mono',monospace; letter-spacing:.06em; }.status-pill.ok { color:var(--green-ink); background:var(--green-wash); }.status-pill.warning { color:var(--red); background:rgba(185,61,60,.08); }.summary { display:grid; grid-template-columns:repeat(3,1fr); border:1px solid var(--soft-line); border-radius:7px; overflow:hidden; }.summary div { display:grid; gap:3px; padding:11px 13px; border-right:1px solid var(--soft-line); }.summary div:last-child { border:0; }.summary b { font:500 20px 'IBM Plex Mono',monospace; color:var(--ink); }.summary span { color:var(--faint); font-size:10px; }.summary .good b { color:var(--green); }.summary .bad b { color:var(--red); }.error-block { display:grid; gap:8px; }.error-toolbar { display:flex; justify-content:space-between; align-items:center; }.error-toolbar strong { font-size:11px; }.report { border:0; background:transparent; color:var(--green-ink); font-size:11px; font-weight:600; }.errors { overflow:auto; max-height:175px; border:1px solid var(--soft-line); border-radius:7px; } table { width:100%; border-collapse:collapse; font-size:10px; } th { position:sticky; top:0; background:var(--field); color:var(--text); font:500 9px 'IBM Plex Mono',monospace; letter-spacing:.04em; } th,td { text-align:left; padding:8px 9px; border-bottom:1px solid var(--soft-line); vertical-align:top; } td { color:var(--text); line-height:1.35; } tr:last-child td { border:0; } code { color:var(--red); font:9px 'IBM Plex Mono',monospace; white-space:nowrap; } @media (max-width:560px) { .format-picker { grid-template-columns:1fr 1fr; }.format-picker .download { grid-column:1/-1; height:36px; text-align:center; }.step-actions { align-items:stretch; flex-direction:column; }.validate { width:100%; }.progress span { display:none; }.summary b { font-size:17px; } }
</style>
